// ---- Circuit (Kit 3) ----
// 74HC595: SER -> D12, SRCLK -> D13, RCLK -> A2, /OE -> GND, /SRCLR -> 5V; Q0-Q7 -> 220 ohm -> 8 LEDs -> GND
#define SR_DATA 12
#define SR_CLOCK 13
#define SR_LATCH A2

void srWrite(byte v) {                      // send 8 bits to the 74HC595 and latch them onto Q0-Q7
  digitalWrite(SR_LATCH, LOW);
  shiftOut(SR_DATA, SR_CLOCK, MSBFIRST, v);
  digitalWrite(SR_LATCH, HIGH);
}
void srBegin() {
  pinMode(SR_DATA, OUTPUT); pinMode(SR_CLOCK, OUTPUT); pinMode(SR_LATCH, OUTPUT);
  srWrite(0);
}

int count = 0;

void setup() {
  srBegin();
  Serial.begin(9600);
}

void loop() {
  srWrite(count);
  Serial.print("count = "); Serial.println(count);
  count = (count + 1) % 256;
  delay(200);
}

// ---- Circuit (Kit 3) ----
// KY-040 encoder: + 5V, GND, CLK -> D7, DT -> D8, SW -> D9
#define ENC_CLK 7
#define ENC_DT 8
#define ENC_SW 9

int encLast = HIGH;
void encBegin() {
  pinMode(ENC_CLK, INPUT_PULLUP);
  pinMode(ENC_DT, INPUT_PULLUP);
  pinMode(ENC_SW, INPUT_PULLUP);
  encLast = digitalRead(ENC_CLK);
}
int encStep() {                            // +1 per clockwise detent, -1 per counter-clockwise detent, 0 when idle
  int c = digitalRead(ENC_CLK), d = 0;
  if (c != encLast && c == LOW) d = (digitalRead(ENC_DT) == HIGH) ? 1 : -1;
  encLast = c;
  return d;
}
int encSwLast = HIGH;
bool encClicked() {                        // true once per push of the encoder shaft
  int now = digitalRead(ENC_SW);
  bool hit = (encSwLast == HIGH && now == LOW);
  encSwLast = now;
  if (hit) delay(20);
  return hit;
}

int position = 0;

void setup() {
  Serial.begin(9600);
  encBegin();
  Serial.println("Turn the encoder - push the shaft to reset");
}

void loop() {
  int s = encStep();
  if (s != 0) {
    position += s;
    Serial.print(s > 0 ? "clockwise      " : "counter-clockwise ");
    Serial.print("position = "); Serial.println(position);
  }
  if (encClicked()) { position = 0; Serial.println("reset to 0"); }
}

