// ---- Circuit (Kit 3) ----
// TM1637: VCC 5V, GND, CLK -> D10, DIO -> D11
// Push button between D2 and GND (INPUT_PULLUP, pressed = LOW)
#define TM_CLK 10
#define TM_DIO 11
#define BTN1 2

#include <TM1637Display.h>
TM1637Display tm(TM_CLK, TM_DIO);

bool running = false;
unsigned long startMs = 0, accum = 0;

unsigned long elapsed() {
  return running ? accum + (millis() - startMs) : accum;
}

void show() {
  unsigned long cs = elapsed() / 10;       // hundredths of a second
  int secs = (cs / 100) % 100;
  int hund = cs % 100;
  tm.showNumberDecEx(secs * 100 + hund, 0x40, true);    // 0x40 lights the colon
}

void setup() {
  pinMode(BTN1, INPUT_PULLUP);
  tm.setBrightness(7);
  show();
  Serial.begin(9600);
}

void loop() {
  if (digitalRead(BTN1) == LOW) {
    unsigned long t0 = millis();
    while (digitalRead(BTN1) == LOW && millis() - t0 < 1000) show();
    if (digitalRead(BTN1) == LOW) {                       // still held: long press
      if (!running) { accum = 0; Serial.println("reset"); }
      while (digitalRead(BTN1) == LOW) show();
    } else if (running) {                                 // short press: stop
      accum += millis() - startMs;
      running = false;
      Serial.print("stopped at "); Serial.print(accum / 1000.0, 2); Serial.println(" s");
    } else {                                              // short press: start
      startMs = millis();
      running = true;
      Serial.println("running");
    }
    delay(30);
  }
  show();
  delay(10);
}

// ---- Circuit (Kit 3) ----
// TM1637: VCC 5V, GND, CLK -> D10, DIO -> D11
// KY-040 encoder: + 5V, GND, CLK -> D7, DT -> D8, SW -> D9
// Red LED anode -> 220 ohm -> D3, cathode -> GND
#define TM_CLK 10
#define TM_DIO 11
#define ENC_CLK 7
#define ENC_DT 8
#define ENC_SW 9
#define RED_LED 3

#include <TM1637Display.h>
TM1637Display tm(TM_CLK, TM_DIO);
int encLast = HIGH;
void encBegin() {
  pinMode(ENC_CLK, INPUT_PULLUP);
  pinMode(ENC_DT, INPUT_PULLUP);
  pinMode(ENC_SW, INPUT_PULLUP);
  encLast = digitalRead(ENC_CLK);
}
int encStep() {                            // +1 per clockwise detent, -1 per counter-clockwise detent, 0 when idle
  int c = digitalRead(ENC_CLK), d = 0;
  if (c != encLast && c == LOW) d = (digitalRead(ENC_DT) == HIGH) ? 1 : -1;
  encLast = c;
  return d;
}
int encSwLast = HIGH;
bool encClicked() {                        // true once per push of the encoder shaft
  int now = digitalRead(ENC_SW);
  bool hit = (encSwLast == HIGH && now == LOW);
  encSwLast = now;
  if (hit) delay(20);
  return hit;
}

int setSecs = 30;
bool counting = false;
long endMs = 0;

void showTime(long secs) {
  tm.showNumberDecEx((secs / 60) * 100 + secs % 60, 0x40, true);
}

void setup() {
  pinMode(RED_LED, OUTPUT);
  encBegin();
  tm.setBrightness(7);
  showTime(setSecs);
  Serial.begin(9600);
}

void loop() {
  if (!counting) {
    int s = encStep();
    if (s != 0) { setSecs = constrain(setSecs + s * 5, 5, 5999); showTime(setSecs); }
    if (encClicked()) {
      counting = true;
      endMs = millis() + setSecs * 1000L;
      Serial.print("countdown started: "); Serial.print(setSecs); Serial.println(" s");
    }
  } else {
    long left = endMs - millis();
    if (left <= 0) {
      Serial.println("TIME UP");
      for (int i = 0; i < 6; i++) {
        digitalWrite(RED_LED, HIGH); showTime(0); delay(200);
        digitalWrite(RED_LED, LOW); tm.clear(); delay(200);
      }
      counting = false;
      showTime(setSecs);
    } else {
      showTime((left + 999) / 1000);
    }
  }
}

// ---- Circuit (Kit 3) ----
// MAX7219 matrix: VCC 5V, GND, DIN -> D12, CLK -> D13, CS -> A2
// Joystick: +5V, GND, VRx -> A0, VRy -> A1, SW -> A3 (INPUT_PULLUP)
#define MAT_DIN 12
#define MAT_CLK 13
#define MAT_CS A2
#define JOY_X A0
#define JOY_Y A1
#define JOY_SW A3

#include <LedControl.h>
LedControl mat = LedControl(MAT_DIN, MAT_CLK, MAT_CS, 1);

int px = -1, py = -1;

void setup() {
  mat.shutdown(0, false);
  mat.setIntensity(0, 4);
  mat.clearDisplay(0);
  pinMode(JOY_SW, INPUT_PULLUP);
}

void loop() {
  int col = constrain(map(analogRead(JOY_X), 0, 1023, 0, 8), 0, 7);     // 0..1023 -> 8 zones
  int row = constrain(map(analogRead(JOY_Y), 0, 1023, 0, 8), 0, 7);
  if (col != px || row != py) {
    bool trail = (digitalRead(JOY_SW) == LOW);
    if (px >= 0 && !trail) mat.setLed(0, py, px, false);   // erase the old dot unless drawing a trail
    mat.setLed(0, row, col, true);
    px = col; py = row;
  }
  delay(30);
}

