// ---- Circuit (Kit 3) ----
// SSD1306 OLED (I2C, address 0x3C): VCC 5V, GND, SDA -> A4, SCL -> A5 (shares the bus with the LCD)
// Joystick: +5V, GND, VRx -> A0, VRy -> A1, SW -> A3 (INPUT_PULLUP)
#define JOY_X A0
#define JOY_Y A1
#define JOY_SW A3

#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>
Adafruit_SSD1306 oled(128, 64, &Wire, -1);

int hist[32];

void setup() {
  oled.begin(SSD1306_SWITCHCAPVCC, 0x3C);
  for (int i = 0; i < 32; i++) hist[i] = 0;
}

void loop() {
  int v = analogRead(JOY_X);
  for (int i = 0; i < 31; i++) hist[i] = hist[i + 1];     // scroll the history left
  hist[31] = map(v, 0, 1023, 0, 40);

  oled.clearDisplay();
  oled.setTextSize(1);
  oled.setTextColor(SSD1306_WHITE);
  oled.setCursor(0, 0);
  oled.print("Joystick X: ");
  oled.print(map(v, 0, 1023, 0, 100));
  oled.print("%");
  oled.drawRect(0, 12, 128, 9, SSD1306_WHITE);
  oled.fillRect(2, 14, map(v, 0, 1023, 0, 124), 5, SSD1306_WHITE);
  for (int i = 0; i < 32; i++) oled.fillRect(i * 4, 63 - hist[i], 3, hist[i] + 1, SSD1306_WHITE);
  oled.display();
  delay(60);
}

// ---- Circuit (Kit 3) ----
// SSD1306 OLED (I2C, address 0x3C): VCC 5V, GND, SDA -> A4, SCL -> A5 (shares the bus with the LCD)


#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>
Adafruit_SSD1306 oled(128, 64, &Wire, -1);

String two(int v) {
  return v < 10 ? String("0") + String(v) : String(v);
}

void hand(int cx, int cy, float deg, int len) {
  float a = (deg - 90) * 3.14159 / 180.0;
  oled.drawLine(cx, cy, cx + len * cos(a), cy + len * sin(a), SSD1306_WHITE);
}

void setup() {
  oled.begin(SSD1306_SWITCHCAPVCC, 0x3C);
}

void loop() {
  long t = 10 * 3600L + 8 * 60L + millis() / 1000;          // the clock starts at 10:08:00
  int s = t % 60, m = (t / 60) % 60, h = (t / 3600) % 12;
  oled.clearDisplay();
  oled.drawCircle(32, 32, 30, SSD1306_WHITE);
  for (int i = 0; i < 12; i++) {                            // 12 hour ticks
    float a = i * 30 * 3.14159 / 180.0;
    oled.drawLine(32 + 26 * cos(a), 32 + 26 * sin(a), 32 + 29 * cos(a), 32 + 29 * sin(a), SSD1306_WHITE);
  }
  hand(32, 32, h * 30 + m * 0.5, 15);
  hand(32, 32, m * 6, 23);
  hand(32, 32, s * 6, 27);
  oled.setTextSize(1);
  oled.setCursor(72, 20);
  oled.print(two(h == 0 ? 12 : h)); oled.print(":"); oled.print(two(m));
  oled.setCursor(72, 32);
  oled.print(":"); oled.print(two(s));
  oled.display();
  delay(100);
}

// ---- Circuit (Kit 3) ----
// MAX7219 matrix: VCC 5V, GND, DIN -> D12, CLK -> D13, CS -> A2
// TM1637: VCC 5V, GND, CLK -> D10, DIO -> D11
// Push button between D2 and GND (INPUT_PULLUP, pressed = LOW)
#define MAT_DIN 12
#define MAT_CLK 13
#define MAT_CS A2
#define TM_CLK 10
#define TM_DIO 11
#define BTN1 2

#include <LedControl.h>
LedControl mat = LedControl(MAT_DIN, MAT_CLK, MAT_CS, 1);
#include <TM1637Display.h>
TM1637Display tm(TM_CLK, TM_DIO);
int lastBtn = HIGH;
bool pressed() {                           // true once per button press (debounced)
  int now = digitalRead(BTN1);
  bool hit = (lastBtn == HIGH && now == LOW);
  lastBtn = now;
  if (hit) delay(25);
  return hit;
}

// the 9 pip positions of a die (3x3, row by row) as a bit mask per face
int FACE[7] = {0, 16, 257, 273, 325, 341, 365};
int total = 0;

void showFace(int face) {
  mat.clearDisplay(0);
  for (int p = 0; p < 9; p++) {
    if (FACE[face] & (1 << p)) {
      int r0 = (p / 3) * 3, c0 = (p % 3) * 3;               // every pip is a 2x2 block
      for (int dr = 0; dr < 2; dr++) for (int dc = 0; dc < 2; dc++) mat.setLed(0, r0 + dr, c0 + dc, true);
    }
  }
}

void setup() {
  pinMode(BTN1, INPUT_PULLUP);
  mat.shutdown(0, false);
  mat.setIntensity(0, 4);
  mat.clearDisplay(0);
  tm.setBrightness(7);
  tm.showNumberDec(0);
  showFace(6);
  Serial.begin(9600);
}

void loop() {
  if (pressed()) {
    randomSeed(micros());
    for (int i = 0; i < 8; i++) { showFace(random(1, 7)); delay(60 + i * 15); }   // rolling...
    int face = random(1, 7);
    showFace(face);
    total += face;
    tm.showNumberDec(total);
    Serial.print("rolled "); Serial.print(face); Serial.print("  total "); Serial.println(total);
  }
}

// ---- Circuit (Kit 3) ----
// TM1637: VCC 5V, GND, CLK -> D10, DIO -> D11
// Push button between D2 and GND (INPUT_PULLUP, pressed = LOW)
#define TM_CLK 10
#define TM_DIO 11
#define BTN1 2

#include <TM1637Display.h>
TM1637Display tm(TM_CLK, TM_DIO);

int scoreA = 0, scoreB = 0;

void show() {
  tm.showNumberDecEx(scoreA * 100 + scoreB, 0x40, true);   // team A on the left two digits, team B on the right
}

void setup() {
  pinMode(BTN1, INPUT_PULLUP);
  tm.setBrightness(7);
  show();
  Serial.begin(9600);
}

void loop() {
  if (digitalRead(BTN1) == LOW) {
    unsigned long t0 = millis();
    while (digitalRead(BTN1) == LOW) { }
    if (millis() - t0 > 600) { scoreB = (scoreB + 1) % 100; Serial.print("Team B scores - "); }
    else                     { scoreA = (scoreA + 1) % 100; Serial.print("Team A scores - "); }
    Serial.print(scoreA); Serial.print(" : "); Serial.println(scoreB);
    show();
    delay(40);
  }
}

// ---- Circuit (Kit 3) ----
// SSD1306 OLED (I2C, address 0x3C): VCC 5V, GND, SDA -> A4, SCL -> A5 (shares the bus with the LCD)
// Joystick: +5V, GND, VRx -> A0, VRy -> A1, SW -> A3 (INPUT_PULLUP)
// Push button between D2 and GND (INPUT_PULLUP, pressed = LOW)
#define JOY_X A0
#define JOY_Y A1
#define JOY_SW A3
#define BTN1 2

#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>
Adafruit_SSD1306 oled(128, 64, &Wire, -1);

int x = 64, y = 32;

void setup() {
  pinMode(BTN1, INPUT_PULLUP);
  oled.begin(SSD1306_SWITCHCAPVCC, 0x3C);
  oled.clearDisplay();
  oled.drawPixel(x, y, SSD1306_WHITE);
  oled.display();
}

void loop() {
  if (digitalRead(BTN1) == LOW) {                          // shake to erase
    oled.clearDisplay();
    oled.drawPixel(x, y, SSD1306_WHITE);
    oled.display();
    delay(250);
  }
  int dx = analogRead(JOY_X) - 512;
  int dy = analogRead(JOY_Y) - 512;
  int nx = x, ny = y;
  if (dx > 150) nx++;
  if (dx < -150) nx--;
  if (dy > 150) ny++;
  if (dy < -150) ny--;
  nx = constrain(nx, 0, 127);
  ny = constrain(ny, 0, 63);
  if (nx != x || ny != y) {
    oled.drawLine(x, y, nx, ny, SSD1306_WHITE);
    x = nx; y = ny;
    oled.display();
  }
  delay(15);
}

