#include <Wire.h>
#include <LiquidCrystal_I2C.h>
LiquidCrystal_I2C lcd(0x27, 16, 2);

void lcdRow(int row, String s) {           // write one full 16-character row (pads with spaces)
  while (s.length() < 16) s += " ";
  lcd.setCursor(0, row);
  lcd.print(s);
}

byte heartBig[8]   = {0x00, 0x0A, 0x1F, 0x1F, 0x1F, 0x0E, 0x04, 0x00};
byte heartSmall[8] = {0x00, 0x00, 0x0A, 0x1F, 0x0E, 0x04, 0x00, 0x00};
byte bat0[8] = {0x0E, 0x1B, 0x11, 0x11, 0x11, 0x11, 0x1F, 0x00};
byte bat1[8] = {0x0E, 0x1B, 0x11, 0x11, 0x1F, 0x1F, 0x1F, 0x00};
byte bat2[8] = {0x0E, 0x1B, 0x1F, 0x1F, 0x1F, 0x1F, 0x1F, 0x00};
byte bat3[8] = {0x0E, 0x1F, 0x1F, 0x1F, 0x1F, 0x1F, 0x1F, 0x00};
byte arrow[8] = {0x00, 0x04, 0x02, 0x1F, 0x02, 0x04, 0x00, 0x00};

int tick = 0;

void setup() {
  lcd.init();
  lcd.backlight();
  lcd.createChar(0, heartBig);
  lcd.createChar(1, heartSmall);
  lcd.createChar(2, bat0);
  lcd.createChar(3, bat1);
  lcd.createChar(4, bat2);
  lcd.createChar(5, bat3);
  lcd.createChar(6, arrow);
  lcdRow(0, "Custom chars");
}

void loop() {
  lcd.setCursor(0, 1);
  lcd.write(tick % 2 == 0 ? 0 : 1);        // heart beats
  lcd.print(" ");
  lcd.write(2 + tick % 4);                 // battery fills up
  lcd.print(" ");
  for (int i = 0; i < 8; i++) {            // arrow runs along the row
    if (i == tick % 8) lcd.write(6); else lcd.print(" ");
  }
  tick++;
  delay(400);
}

// ---- Circuit (Kit 3) ----
// 74HC595: SER -> D12, SRCLK -> D13, RCLK -> A2, /OE -> GND, /SRCLR -> 5V; Q0-Q7 -> 220 ohm -> 8 LEDs -> GND
// Joystick: +5V, GND, VRx -> A0, VRy -> A1, SW -> A3 (INPUT_PULLUP)
#define SR_DATA 12
#define SR_CLOCK 13
#define SR_LATCH A2
#define JOY_X A0
#define JOY_Y A1
#define JOY_SW A3

void srWrite(byte v) {                      // send 8 bits to the 74HC595 and latch them onto Q0-Q7
  digitalWrite(SR_LATCH, LOW);
  shiftOut(SR_DATA, SR_CLOCK, MSBFIRST, v);
  digitalWrite(SR_LATCH, HIGH);
}
void srBegin() {
  pinMode(SR_DATA, OUTPUT); pinMode(SR_CLOCK, OUTPUT); pinMode(SR_LATCH, OUTPUT);
  srWrite(0);
}

int lastLevel = -1;

void setup() {
  srBegin();
  Serial.begin(9600);
}

void loop() {
  int level = constrain(map(analogRead(JOY_Y), 0, 1023, 0, 9), 0, 8);     // 9 zones: 0 .. 8 LEDs
  if (level != lastLevel) {
    lastLevel = level;
    srWrite((1 << level) - 1);             // level 3 -> 00000111
    Serial.print("level "); Serial.print(level); Serial.println(" / 8");
  }
  delay(40);
}

