// 16x2 LCD (I2C, address 0x27): VCC 5V, GND, SDA -> A4, SCL -> A5
// KY-040 encoder: + 5V, GND, CLK -> D7, DT -> D8, SW -> D9
// Push button between D2 and GND (INPUT_PULLUP, pressed = LOW)
#define ENC_CLK 7
#define ENC_DT 8
#define ENC_SW 9
#define BTN1 2

#include <Wire.h>
#include <LiquidCrystal_I2C.h>
LiquidCrystal_I2C lcd(0x27, 16, 2);

void lcdRow(int row, String s) {           // write one full 16-character row (pads with spaces)
  while (s.length() < 16) s += " ";
  lcd.setCursor(0, row);
  lcd.print(s);
}
int encLast = HIGH;
void encBegin() {
  pinMode(ENC_CLK, INPUT_PULLUP);
  pinMode(ENC_DT, INPUT_PULLUP);
  pinMode(ENC_SW, INPUT_PULLUP);
  encLast = digitalRead(ENC_CLK);
}
int encStep() {                            // +1 per clockwise detent, -1 per counter-clockwise detent, 0 when idle
  int c = digitalRead(ENC_CLK), d = 0;
  if (c != encLast && c == LOW) d = (digitalRead(ENC_DT) == HIGH) ? 1 : -1;
  encLast = c;
  return d;
}
int encSwLast = HIGH;
bool encClicked() {                        // true once per push of the encoder shaft
  int now = digitalRead(ENC_SW);
  bool hit = (encSwLast == HIGH && now == LOW);
  encSwLast = now;
  if (hit) delay(20);
  return hit;
}
int lastBtn = HIGH;
bool pressed() {                           // true once per button press (debounced)
  int now = digitalRead(BTN1);
  bool hit = (lastBtn == HIGH && now == LOW);
  lastBtn = now;
  if (hit) delay(25);
  return hit;
}

int secret = 0, guess = 50, tries = 0;

void showGuess(String hint) {
  lcdRow(0, "Guess: " + String(guess));
  lcdRow(1, hint);
}

void setup() {
  pinMode(BTN1, INPUT_PULLUP);
  encBegin();
  lcd.init();
  lcd.backlight();
  showGuess("Turn, then press");
  Serial.begin(9600);
}

void loop() {
  int s = encStep();
  if (s != 0) {
    if (secret == 0) { randomSeed(micros()); secret = random(1, 101); }   // seeded by the moment you first touch the knob
    guess = constrain(guess + s, 1, 100);
    showGuess("Turn, then press");
  }
  if (pressed() && secret != 0) {
    tries++;
    if (guess < secret) showGuess("TOO LOW");
    else if (guess > secret) showGuess("TOO HIGH");
    else {
      lcdRow(0, "YOU WIN! It was " + String(secret));
      lcdRow(1, "Tries: " + String(tries));
      Serial.print("won in "); Serial.print(tries); Serial.println(" tries");
      while (!pressed()) { }               // press again for a new game
      secret = 0; tries = 0; guess = 50;
      showGuess("New game");
    }
  }
}

// ---- Circuit (Kit 3) ----
// MAX7219 matrix: VCC 5V, GND, DIN -> D12, CLK -> D13, CS -> A2
#define MAT_DIN 12
#define MAT_CLK 13
#define MAT_CS A2

#include <LedControl.h>
LedControl mat = LedControl(MAT_DIN, MAT_CLK, MAT_CS, 1);

// each frame = 8 bytes (one per row)
byte HEART[] = {
  0x00, 0x00, 0x14, 0x3E, 0x3E, 0x1C, 0x08, 0x00,     // small
  0x00, 0x66, 0xFF, 0xFF, 0xFF, 0x7E, 0x3C, 0x18,     // big
  0x00, 0x00, 0x14, 0x3E, 0x3E, 0x1C, 0x08, 0x00,     // small
  0x00, 0x00, 0x00, 0x14, 0x1C, 0x08, 0x00, 0x00      // tiny
};
byte RAIN[] = {0x42, 0x00, 0x10, 0x00, 0x84, 0x00, 0x21, 0x00};   // drops: the pattern falls one row per frame

void drawFrame(int row, byte bits) {
  mat.setRow(0, row, bits);
}

void setup() {
  mat.shutdown(0, false);
  mat.setIntensity(0, 4);
  mat.clearDisplay(0);
}

void loop() {
  for (int rep = 0; rep < 3; rep++) {                    // heartbeat x3
    for (int f = 0; f < 4; f++) {
      for (int r = 0; r < 8; r++) drawFrame(r, HEART[f * 8 + r]);
      delay(f == 1 ? 200 : 150);
    }
  }
  for (int k = 0; k < 24; k++) {                         // rain: rotate the pattern downwards
    for (int r = 0; r < 8; r++) drawFrame(r, RAIN[(r - k % 8 + 8) % 8]);
    delay(110);
  }
}

