// ---- Circuit (Kit 3) ----
// SSD1306 OLED (I2C, address 0x3C): VCC 5V, GND, SDA -> A4, SCL -> A5 (shares the bus with the LCD)


#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>
Adafruit_SSD1306 oled(128, 64, &Wire, -1);

String screen = "";

void redraw() {
  oled.clearDisplay();
  oled.setTextSize(1);
  oled.setTextColor(SSD1306_WHITE);
  oled.setCursor(0, 0);
  oled.print(screen);
  oled.print("_");
  oled.display();
}

void setup() {
  Serial.begin(9600);
  oled.begin(SSD1306_SWITCHCAPVCC, 0x3C);
  screen = "OLED terminal ready.\n";
  redraw();
  Serial.println("Type something and press Send");
}

void loop() {
  bool changed = false;
  while (Serial.available() > 0) {
    char c = Serial.read();
    if (c == '\r') continue;
    screen += c;
    changed = true;
  }
  if (changed) {
    while (screen.length() > 126) screen = screen.substring(21);   // drop the oldest text so the screen scrolls
    redraw();
  }
}

// ---- Circuit (Kit 3) ----
// 16x2 LCD (I2C, address 0x27): VCC 5V, GND, SDA -> A4, SCL -> A5
// Push button between D2 and GND (INPUT_PULLUP, pressed = LOW)
// Green LED anode -> 220 ohm -> D5, cathode -> GND
#define BTN1 2
#define GREEN_LED 5

#include <Wire.h>
#include <LiquidCrystal_I2C.h>
LiquidCrystal_I2C lcd(0x27, 16, 2);

void lcdRow(int row, String s) {           // write one full 16-character row (pads with spaces)
  while (s.length() < 16) s += " ";
  lcd.setCursor(0, row);
  lcd.print(s);
}

int best = 9999;

bool buttonDown() { return digitalRead(BTN1) == LOW; }
void waitRelease() { while (buttonDown()) { } delay(40); }

void setup() {
  pinMode(BTN1, INPUT_PULLUP);
  pinMode(GREEN_LED, OUTPUT);
  lcd.init();
  lcd.backlight();
  lcdRow(0, "Reaction game");
  lcdRow(1, "Press to start");
  Serial.begin(9600);
}

void loop() {
  if (!buttonDown()) return;
  waitRelease();
  lcdRow(0, "Wait for green..");
  lcdRow(1, "");
  randomSeed(micros());
  unsigned long goAt = millis() + random(2000, 5000);
  bool early = false;
  while (millis() < goAt) {
    if (buttonDown()) { early = true; break; }
  }
  if (early) {
    lcdRow(0, "Too soon!");
    lcdRow(1, "Press to retry");
    waitRelease();
    return;
  }
  digitalWrite(GREEN_LED, HIGH);
  unsigned long t0 = millis();
  while (!buttonDown()) { }
  int ms = millis() - t0;
  digitalWrite(GREEN_LED, LOW);
  if (ms < best) best = ms;
  lcdRow(0, "Time: " + String(ms) + " ms");
  lcdRow(1, "Best: " + String(best) + " ms");
  Serial.print("reaction "); Serial.print(ms); Serial.println(" ms");
  waitRelease();
}

