void serve() {
  randomSeed(micros());
  bx = random(1, 7); by = 0; vy = 1;
  vx = (random(0, 2) == 0) ? -1 : 1;
  score = 0;
  tm.showNumberDec(0);
  playing = true;
  draw();
}

void gameOver() {
  playing = false;
  Serial.print("game over - score "); Serial.println(score);
  for (int i = 0; i < 3; i++) { mat.clearDisplay(0); delay(150); draw(); delay(150); }
}

void setup() {
  pinMode(BTN1, INPUT_PULLUP);
  encBegin();
  mat.shutdown(0, false);
  mat.setIntensity(0, 4);
  mat.clearDisplay(0);
  tm.setBrightness(7);
  tm.showNumberDec(0);
  draw();
  Serial.begin(9600);
}

void loop() {
  int s = encStep();
  if (s != 0) { padX = constrain(padX + s, 0, 5); draw(); }
  if (!playing) {
    if (pressed()) serve();
    return;
  }
  if (millis() - lastStep >= max(70, 260 - score * 12)) {      // the ball speeds up with every return
    lastStep = millis();
    if (bx + vx < 0 || bx + vx > 7) vx = -vx;
    bx += vx;
    by += vy;
    if (by <= 0) { by = 0; vy = 1; }
    if (by >= 7) {                                              // ball reached the paddle row
      if (bx >= padX && bx <= padX + 2) { by = 6; vy = -1; score++; tm.showNumberDec(score); }
      else { draw(); gameOver(); return; }
    }
    draw();
  }
}

// ---- Circuit (Kit 3) ----
// MAX7219 matrix: VCC 5V, GND, DIN -> D12, CLK -> D13, CS -> A2
// Joystick: +5V, GND, VRx -> A0, VRy -> A1, SW -> A3 (INPUT_PULLUP)
// TM1637: VCC 5V, GND, CLK -> D10, DIO -> D11
#define MAT_DIN 12
#define MAT_CLK 13
#define MAT_CS A2
#define JOY_X A0
#define JOY_Y A1
#define JOY_SW A3
#define TM_CLK 10
#define TM_DIO 11

#include <LedControl.h>
LedControl mat = LedControl(MAT_DIN, MAT_CLK, MAT_CS, 1);
#include <TM1637Display.h>
TM1637Display tm(TM_CLK, TM_DIO);

int sx[64], sy[64];
int len = 3, dirx = 1, diry = 0, fx = 0, fy = 0, score = 0;
unsigned long lastStep = 0;

bool onSnake(int x, int y) {
  for (int i = 0; i < len; i++) if (sx[i] == x && sy[i] == y) return true;
  return false;
}

void placeFood() {
  bool ok = false;
  while (!ok) {
    fx = random(0, 8); fy = random(0, 8);
    ok = !onSnake(fx, fy);
  }
}

void draw() {
  mat.clearDisplay(0);
  for (int i = 0; i < len; i++) mat.setLed(0, sy[i], sx[i], true);
  mat.setLed(0, fy, fx, true);
}

void newGame() {
  len = 3; score = 0; dirx = 1; diry = 0;
  sx[0] = 4; sy[0] = 4; sx[1] = 3; sy[1] = 4; sx[2] = 2; sy[2] = 4;
  placeFood();
  tm.showNumberDec(0);
  draw();
}

void setup() {
  mat.shutdown(0, false);
  mat.setIntensity(0, 4);
  mat.clearDisplay(0);
  tm.setBrightness(7);
  Serial.begin(9600);
  randomSeed(micros());
  newGame();
}

void loop() {
  int dx = analogRead(JOY_X) - 512, dy = analogRead(JOY_Y) - 512;
  if (abs(dx) > abs(dy) && abs(dx) > 250) {                       // steer, but never reverse into yourself
    if (dx > 0 && dirx != -1) { dirx = 1; diry = 0; }
    if (dx < 0 && dirx != 1) { dirx = -1; diry = 0; }
  } else if (abs(dy) > 250) {
    if (dy > 0 && diry != -1) { dirx = 0; diry = 1; }
    if (dy < 0 && diry != 1) { dirx = 0; diry = -1; }
  }
  if (millis() - lastStep < max(100, 320 - score * 15)) return;
  lastStep = millis();
  int nx = sx[0] + dirx, ny = sy[0] + diry;
  bool hitTail = onSnake(nx, ny) && !(nx == sx[len - 1] && ny == sy[len - 1]);
  if (nx < 0 || nx > 7 || ny < 0 || ny > 7 || hitTail) {
    Serial.print("crash! apples = "); Serial.println(score);
    for (int i = 0; i < 3; i++) { mat.clearDisplay(0); delay(150); draw(); delay(150); }
    delay(600);
    newGame();
    return;
  }
  bool eat = (nx == fx && ny == fy);
  if (eat && len < 63) len++;
  for (int i = len - 1; i > 0; i--) { sx[i] = sx[i - 1]; sy[i] = sy[i - 1]; }
  sx[0] = nx; sy[0] = ny;
  if (eat) { score++; tm.showNumberDec(score); placeFood(); }
  draw();
}

// ---- Circuit (Kit 3) ----
// SSD1306 OLED (I2C, address 0x3C): VCC 5V, GND, SDA -> A4, SCL -> A5 (shares the bus with the LCD)
// KY-040 encoder: + 5V, GND, CLK -> D7, DT -> D8, SW -> D9
// 16x2 LCD (I2C, address 0x27): VCC 5V, GND, SDA -> A4, SCL -> A5
// Push button between D2 and GND (INPUT_PULLUP, pressed = LOW)
#define ENC_CLK 7
#define ENC_DT 8
#define ENC_SW 9
#define BTN1 2

#include <Wire.h>
#include <Adafruit_GFX.h>
#include <Adafruit_SSD1306.h>
Adafruit_SSD1306 oled(128, 64, &Wire, -1);
#include <Wire.h>
#include <LiquidCrystal_I2C.h>
LiquidCrystal_I2C lcd(0x27, 16, 2);

void lcdRow(int row, String s) {           // write one full 16-character row (pads with spaces)
  while (s.length() < 16) s += " ";
  lcd.setCursor(0, row);
  lcd.print(s);
}
int encLast = HIGH;
void encBegin() {
  pinMode(ENC_CLK, INPUT_PULLUP);
  pinMode(ENC_DT, INPUT_PULLUP);
  pinMode(ENC_SW, INPUT_PULLUP);
  encLast = digitalRead(ENC_CLK);
}
int encStep() {                            // +1 per clockwise detent, -1 per counter-clockwise detent, 0 when idle
  int c = digitalRead(ENC_CLK), d = 0;
  if (c != encLast && c == LOW) d = (digitalRead(ENC_DT) == HIGH) ? 1 : -1;
  encLast = c;
  return d;
}
int encSwLast = HIGH;
bool encClicked() {                        // true once per push of the encoder shaft
  int now = digitalRead(ENC_SW);
  bool hit = (encSwLast == HIGH && now == LOW);
  encSwLast = now;
  if (hit) delay(20);
  return hit;
}
int lastBtn = HIGH;
bool pressed() {                           // true once per button press (debounced)
  int now = digitalRead(BTN1);
  bool hit = (lastBtn == HIGH && now == LOW);
  lastBtn = now;
  if (hit) delay(25);
  return hit;
}

int padX = 52;                                  // paddle left edge, 24 px wide
float bx = 64, by = 57, vx = 1.2, vy = -1.6;
bool bricks[24];
int lives = 3, score = 0, bricksLeft = 24;
bool launched = false, finished = false;
unsigned long lastFrame = 0;

void showStatus() {
  if (finished) {
    lcdRow(0, bricksLeft == 0 ? "YOU WIN!" : "GAME OVER");
    lcdRow(1, "Score: " + String(score));
  } else {
    lcdRow(0, "Lives: " + String(lives));
    lcdRow(1, "Score: " + String(score));
  }
}

void newGame() {
  for (int i = 0; i < 24; i++) bricks[i] = true;
  bricksLeft = 24; lives = 3; score = 0; finished = false; launched = false;
  showStatus();
}

void render() {
  oled.clearDisplay();
  for (int i = 0; i < 24; i++) if (bricks[i]) oled.fillRect((i % 8) * 16 + 1, 8 + (i / 8) * 6, 14, 5, SSD1306_WHITE);
  oled.fillRect(padX, 60, 24, 3, SSD1306_WHITE);
  oled.fillCircle(bx, by, 2, SSD1306_WHITE);
  oled.display();
}

void setup() {
  pinMode(BTN1, INPUT_PULLUP);
  encBegin();
  oled.begin(SSD1306_SWITCHCAPVCC, 0x3C);
  lcd.init();
  lcd.backlight();
  Serial.begin(9600);
  newGame();
  render();
}

void loop() {
  int s = encStep();
  if (s != 0) padX = constrain(padX + s * 4, 0, 104);
  if (pressed()) {
    if (finished) newGame();
    else if (!launched) { launched = true; vx = 1.2; vy = -1.6; }
  }
  if (millis() - lastFrame < 25) return;
  lastFrame = millis();
  if (!launched) { bx = padX + 12; by = 57; }
  else if (!finished) {
    bx += vx; by += vy;
    if (bx < 2) { bx = 2; vx = -vx; }
    if (bx > 125) { bx = 125; vx = -vx; }
    if (by < 2) { by = 2; vy = -vy; }
    if (vy > 0 && by >= 57 && by <= 61 && bx >= padX - 2 && bx <= padX + 26) {      // paddle: aim with the hit position
      vy = -vy; by = 57;
      vx = (bx - (padX + 12)) / 8.0;
    }
    if (by >= 8 && by < 26) {
      int cell = ((int)((by - 8) / 6)) * 8 + (int)(bx / 16);
      if (bricks[cell]) {
        bricks[cell] = false; bricksLeft--; score += 10; vy = -vy;
        if (bricksLeft == 0) finished = true;
        showStatus();
      }
    }
    if (by > 63) {
      lives--;
      launched = false;
      if (lives == 0) finished = true;
      showStatus();
    }
  }
  render();
}

