byte g[8], nxt[8];
int cx = 0, cy = 0, gen = 0;
bool running = false;
unsigned long last = 0;

bool cell(int r, int c) {
  r = (r + 8) % 8; c = (c + 8) % 8;                 // the board wraps around
  return (g[r] >> (7 - c)) & 1;
}

void draw() {
  bool blink = (millis() / 250) % 2 == 0;
  for (int r = 0; r < 8; r++) {
    byte row = g[r];
    if (!running && r == cy && blink) row = row ^ (0x80 >> cx);
    mat.setRow(0, r, row);
  }
}

void stepLife() {
  for (int r = 0; r < 8; r++) {
    byte row = 0;
    for (int c = 0; c < 8; c++) {
      int n = 0;
      for (int dr = -1; dr <= 1; dr++) for (int dc = -1; dc <= 1; dc++) if (dr != 0 || dc != 0) n += cell(r + dr, c + dc);
      bool alive = cell(r, c);
      if ((alive && (n == 2 || n == 3)) || (!alive && n == 3)) row = row | (0x80 >> c);
    }
    nxt[r] = row;
  }
  for (int r = 0; r < 8; r++) g[r] = nxt[r];
  gen++;
  tm.showNumberDec(gen);
}

void setup() {
  pinMode(BTN1, INPUT_PULLUP);
  pinMode(JOY_SW, INPUT_PULLUP);
  mat.shutdown(0, false);
  mat.setIntensity(0, 4);
  mat.clearDisplay(0);
  tm.setBrightness(7);
  tm.showNumberDec(0);
  g[0] = 0x20; g[1] = 0x10; g[2] = 0x70;            // a glider to start with
  Serial.begin(9600);
}

void loop() {
  if (pressed()) {
    running = !running;
    Serial.println(running ? "running" : "edit mode");
  }
  if (!running) {
    int d = joyDir();
    if (d == 1) cx = (cx + 7) % 8;
    if (d == 2) cx = (cx + 1) % 8;
    if (d == 3) cy = (cy + 7) % 8;
    if (d == 4) cy = (cy + 1) % 8;
    if (joyClicked()) g[cy] = g[cy] ^ (0x80 >> cx);
  } else if (millis() - last >= 300) {
    last = millis();
    stepLife();
  }
  draw();
  delay(20);
}

