String KEYS = "0123456789+-*/=C";
int keyIdx = 0;
String expr = "";
String shown = "";                          // result text while a result is on screen
bool calcErr = false;

long applyOp(long a, char op, long b) {
  if (op == '+') return a + b;
  if (op == '-') return a - b;
  if (op == '*') return a * b;
  if (b == 0) { calcErr = true; return 0; }
  return a / b;
}

long evaluate(String e) {
  calcErr = false;
  long acc = 0, cur = 0;
  char op = '+';
  for (int i = 0; i < e.length(); i++) {
    char c = e.charAt(i);
    if (c >= '0' && c <= '9') cur = cur * 10 + (c - '0');
    else { acc = applyOp(acc, op, cur); op = c; cur = 0; }
  }
  return applyOp(acc, op, cur);
}

void draw() {
  String top = expr;
  while (top.length() > 16) top = top.substring(1);
  lcdRow(0, top);
  if (shown != "") lcdRow(1, "= " + shown);
  else lcdRow(1, "Pick [" + String(KEYS.charAt(keyIdx)) + "] push=OK");
}

void setup() {
  pinMode(BTN1, INPUT_PULLUP);
  pinMode(JOY_SW, INPUT_PULLUP);
  lcd.init();
  lcd.backlight();
  Serial.begin(9600);
  draw();
}

void loop() {
  int d = joyDir();
  if (d == 1) { keyIdx = (keyIdx + 15) % 16; shown = ""; draw(); }
  if (d == 2) { keyIdx = (keyIdx + 1) % 16; shown = ""; draw(); }
  if (pressed()) {                                       // backspace
    if (expr.length() > 0) expr = expr.substring(0, expr.length() - 1);
    shown = ""; draw();
  }
  if (joyClicked()) {
    char k = KEYS.charAt(keyIdx);
    if (k == 'C') { expr = ""; shown = ""; }
    else if (k == '=') {
      long r = evaluate(expr);
      shown = calcErr ? String("Error") : String(r);
      Serial.print(expr); Serial.print(" = "); Serial.println(shown);
      if (!calcErr) expr = String(r);                    // keep calculating with the result
    } else { expr += k; shown = ""; }
    draw();
  }
}

