int wave = 0, freq = 4;                       // freq = cycles on screen
unsigned long lastFrame = 0;

float sample(int x, float phase) {
  float p = x * freq / 128.0 + phase;
  p = p - floor(p);                           // 0..1 inside one cycle
  if (wave == 0) return sin(p * 6.28318);
  if (wave == 1) return 2 * p - 1;
  return p < 0.5 ? 1 : -1;
}

void setup() {
  pinMode(BTN1, INPUT_PULLUP);
  encBegin();
  oled.begin(SSD1306_SWITCHCAPVCC, 0x3C);
  Serial.begin(9600);
}

void loop() {
  int s = encStep();
  if (s != 0) { freq = constrain(freq + s, 1, 20); Serial.print("cycles "); Serial.println(freq); }
  if (pressed()) { wave = (wave + 1) % 3; Serial.print("wave "); Serial.println(wave); }
  if (millis() - lastFrame < 50) return;
  lastFrame = millis();
  float phase = millis() / 600.0;
  oled.clearDisplay();
  oled.drawRect(0, 10, 128, 54, SSD1306_WHITE);
  for (int x = 4; x < 128; x += 8) oled.drawPixel(x, 37, SSD1306_WHITE);       // centre line
  int prevY = 37 - 22 * sample(0, phase);
  for (int x = 1; x < 128; x++) {
    int y = 37 - 22 * sample(x, phase);
    oled.drawLine(x - 1, prevY, x, y, SSD1306_WHITE);
    prevY = y;
  }
  oled.setTextSize(1);
  oled.setTextColor(SSD1306_WHITE);
  oled.setCursor(0, 0);
  oled.print(wave == 0 ? "SINE" : (wave == 1 ? "SAW" : "SQUARE"));
  oled.print("  cycles: "); oled.print(freq);
  oled.display();
}

