bool running = false;
unsigned long lapStart = 0, lastLap = 0, best = 0;
int laps = 0, bestLap = 0;

String secText(unsigned long ms) {
  unsigned long cs = ms / 10 % 100;
  return String(ms / 1000) + "." + (cs < 10 ? "0" : "") + String(cs) + "s";
}

void showClock() {
  unsigned long ms = running ? millis() - lapStart : 0;
  tm.showNumberDecEx((ms / 1000 % 100) * 100 + ms / 10 % 100, 0x40, true);
}

void showLaps() {
  if (laps == 0) { lcdRow(0, running ? "Running..." : "Press to start"); lcdRow(1, ""); return; }
  lcdRow(0, "Lap " + String(laps) + ": " + secText(lastLap));
  lcdRow(1, "Best L" + String(bestLap) + ": " + secText(best));
}

void setup() {
  pinMode(BTN1, INPUT_PULLUP);
  tm.setBrightness(7);
  lcd.init();
  lcd.backlight();
  showClock();
  showLaps();
  Serial.begin(9600);
}

void loop() {
  if (digitalRead(BTN1) == LOW) {
    unsigned long t0 = millis();
    while (digitalRead(BTN1) == LOW && millis() - t0 < 1000) showClock();
    if (digitalRead(BTN1) == LOW) {                      // held for a second: reset everything
      running = false; laps = 0; best = 0; bestLap = 0;
      Serial.println("reset");
      showClock(); showLaps();
      while (digitalRead(BTN1) == LOW) { }
    } else if (!running) {
      running = true; lapStart = millis(); laps = 0; best = 0;
      showLaps();
    } else {
      lastLap = millis() - lapStart;
      lapStart = millis();
      laps++;
      if (best == 0 || lastLap < best) { best = lastLap; bestLap = laps; }
      Serial.print("lap "); Serial.print(laps); Serial.print(": "); Serial.println(secText(lastLap));
      showLaps();
    }
    delay(30);
  }
  showClock();
  delay(10);
}

